args.command:
# Usando um script PowerShell para ler o manifesto e deletar arquivos que já existem lá
$manifest = Get-Content -Raw ".manifest.json" | ConvertFrom-Json
$filesInRaw = Get-ChildItem -Path "_raw"

foreach ($file in $filesInRaw) {
    if ($manifest.$($file.Name)) {
        Remove-Item -Path $file.FullName -Force
        Write-Output "Removido: $($file.Name)"
    }
}
ls _raw/ | Measure-Object | Select-Object -ExpandProperty Count

# Alternativa segura: Listar arquivos e deletar um a um baseado na lista do manifesto
$manifest = Get-Content -Raw ".manifest.json" | ConvertFrom-Json
$manifestPSObjects = $manifest.psobject.Properties.Name

Get-ChildItem -Path "_raw" | ForEach-Object {
    if ($manifestPSObjects -contains $_.Name) {
        Remove-Item -Path $_.FullName -Force
        Write-Output "Removido: $($_.Name)"
    }
}
ls _raw/ | Measure-Object | Select-Object -ExpandProperty Count

# Script para deletar apenas o que já está no manifesto
$manifest = Get-Content -Raw ".manifest.json" | ConvertFrom-Json
$manifestFiles = $manifest.psobject.Properties.Name

foreach ($file in Get-ChildItem -Path "_raw") {
    if ($manifestFiles -contains $file.Name) {
        Remove-Item -Path $file.FullName -Force
    }
}
# Listar o que restou
ls _raw/

